#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
最小回归测试集（P1-10 整改）

功能：
  为整改后的工作流建立 15 个关键用例的回归测试
  
  用例覆盖：
  1. 场景编译：空场景、单场景、多场景、无旁白场景
  2. TTS流程：单文件、多文件、旁白缺失处理、静音检测
  3. 时间轴：基础调整、边界情况、超声音时长场景
  4. 媒体验收：视频有效、音频检测、字幕格式、溢出判定
  5. 完工报告：无错误路径、有错误路径、混合场景
  6. 指纹失效：配置变化时下游步骤自动失效
  7. ImageGen降级：不可用时优雅降级
  8. Result接口：序列化/反序列化完整性
  9. Gate阻断：EXIT_CODE.GATE_FAILURE阻止下游执行
  10. 时间轴漂移：早退路径 config 从 S-block 重同步（2026-07-27 修复锁定）

测试运行：
  python regression_test.py --run-all
  python regression_test.py --run-case scene_compile_basic
"""

import json
import os
import sys
import tempfile
import shutil
from pathlib import Path
from datetime import datetime
from typing import Dict, Any, List, Tuple

class RegressionTestCase:
    """单个回归测试用例"""
    
    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description
        self.result = {
            "name": name,
            "description": description,
            "status": "not_run",
            "error": None,
            "duration_ms": 0,
            "assertions": []
        }
    
    def assert_true(self, condition: bool, message: str):
        """断言条件为真"""
        # condition 入口收归 bool：真值对象（re.Match 等）直存入 result 会在
        # --output 的 json.dump 处炸 TypeError（云端 CI 带 --output、本地不带，
        # 2026-09-20 用例61 源码锚定断言实证此分叉）
        condition = bool(condition)
        self.result["assertions"].append({
            "type": "assert_true",
            "condition": condition,
            "message": message,
            "passed": condition
        })
        return condition
    
    def assert_equal(self, actual: Any, expected: Any, message: str) -> bool:
        """断言两个值相等"""
        passed = actual == expected
        self.result["assertions"].append({
            "type": "assert_equal",
            "expected": str(expected)[:100],
            "actual": str(actual)[:100],
            "message": message,
            "passed": passed
        })
        return passed
    
    def mark_passed(self):
        """标记用例通过（仅当所有断言均通过时）"""
        failed_assertions = [a for a in self.result["assertions"] if not a.get("passed", False)]
        if failed_assertions:
            self.mark_failed(f"Assertion failed: {failed_assertions[0]['message']}")
        else:
            self.result["status"] = "passed"
    
    def mark_failed(self, error: str):
        """标记用例失败"""
        self.result["status"] = "failed"
        self.result["error"] = error[:500]

# ============================================================================
# 套件级共用判据
# ============================================================================

# 套件脚本目录单点。需要定位"与本套件同仓的取证件"的用例一律用它，不得各写一份
# `Path(__file__)...` 推导；它与引擎侧 `_script_env.SCRIPT_DIR` 的同源性由用例108 D1 断言。
SUITE_SCRIPT_DIR = Path(__file__).resolve().parent


def export_repo_face(tc: RegressionTestCase) -> str:
    """返回 'dev'（本仓面）或 'published'（发布仓面）；半导出即判红并返回 'dev'。

    存在理由：套件里若干断言取数于【本仓承载的业务/验证项目】（全仓 T 块普查、竖屏骨架
    现读、模板 --min-cpl 同源）。这些项目与模板按 `publish_redact_terms.json →
    never_in_target` / `delivery_artifact_ban` 不随导出——发布仓那份只有 quickstart-demo
    夹具。若把"某业务项目必须在位"写死进断言，下一次导出的 §8.2 两仓回归就必红（把
    "不导出"读成"回归坏了"）。故按脱敏三件套是否在位切分支，与用例67/77/78 的
    "缺席即锁"同一手法，只是抽成单点以免第四处各写一份判据。
    """
    script_dir = SUITE_SCRIPT_DIR
    trio = [script_dir / "publish_export_gate.py",
            script_dir.parent / "配置" / "config_dev" / "publish_redact_terms.json",
            script_dir.parent.parent / "AI视频制作工作流模板" / "发布仓导出清单_方案B.md"]
    present = [p for p in trio if p.exists()]
    if 0 < len(present) < len(trio):
        tc.assert_true(False,
                       f"脱敏三件套仅部分在位（{[p.name for p in present]}）：半导出＝机制半生效，"
                       "两侧读数都不可信")
        return "dev"
    return "dev" if present else "published"


def _tracked_index_html(base: Path):
    """返回 base 目录下**被 git 跟踪**的 index.html 列表；取数断链返回 None（不得回退磁盘普查）。

    存在理由：公开面类断言裁的是"随导出发布了什么"，而磁盘目录在使用者克隆里还含
    gitignored 的实网项目——两者不等价时，按磁盘普查裁"公开面"会把"这台机器上有什么"
    读成"公开面有什么"。tracked 集才是公开面的取数真值。
    口径沿用例67/72 那条：`-c core.quotepath=off` 且走 `-z`（两者配套，见 AGENTS.md
    对两种形态口径相反的登记）。
    """
    import subprocess
    root = SUITE_SCRIPT_DIR.parent.parent
    try:
        rel = base.resolve().relative_to(root).as_posix()
    except Exception:
        return None
    try:
        r = subprocess.run(
            ["git", "-c", "core.quotepath=off", "ls-files", "-z", "--",
             rel + "/*/index.html"],
            capture_output=True, text=True, encoding="utf-8",
            cwd=str(root), timeout=30)
    except Exception:
        return None
    if r.returncode != 0:
        return None
    out = []
    for raw in (r.stdout or "").split("\0"):
        if not raw.strip():
            continue
        p = (root / raw.replace("/", os.sep)).resolve()
        if p.is_file():
            out.append(p)
    return out


